let $addButtonCertificate=document.getElementById("cert_addCollection");let $blockCollectionCertificate=document.getElementById("cert_collection");if($addButtonCertificate){let $delItemCertificate=$blockCollectionCertificate.querySelectorAll(".del-item-cert");$delItemCertificate.forEach((function(item){item.addEventListener("click",(function(){item.closest(".item-collection-cert").remove()}))}));$addButtonCertificate.addEventListener("click",(function(){let $addButtonCertificate=this;let newForm=document.getElementById($addButtonCertificate.dataset.prototype).dataset.prototype;let index=$addButtonCertificate.dataset.index*1;newForm=newForm.replace(/__certificate__/g,index);let div=document.createElement("div");div.classList.add("d-flex");div.classList.add("justify-content-between");div.classList.add("align-items-center");div.classList.add("gap-3");div.classList.add("item-collection-cert");div.classList.add("mb-3");div.innerHTML=newForm;$blockCollectionCertificate.append(div);div.querySelector(".del-item-cert").addEventListener("click",(function(){this.closest(".item-collection-cert").remove();let index=$addButtonCertificate.dataset.index*1;$addButtonCertificate.dataset.index=(index-1).toString()}));const $elementsSelect2=div.querySelectorAll('[data-select="select2"]');$elementsSelect2.forEach((element=>{new NiceSelect(element,{searchable:true})}));let $elementsDate=div.querySelectorAll("input.js-datepicker");$elementsDate.forEach((element=>{MCDatepicker.create({el:"#"+element.id,bodyType:"modal",autoClose:false,closeOndblclick:true,closeOnBlur:false,customOkBTN:"OK",customClearBTN:datapickerLang[$locale].customClearBTN,customCancelBTN:datapickerLang[$locale].customCancelBTN,firstWeekday:datapickerLang[$locale].firstWeekday,dateFormat:"DD.MM.YYYY",customWeekDays:datapickerLang[$locale].customWeekDays,customMonths:datapickerLang[$locale].customMonths,selectedDate:new Date})}));$addButtonCertificate.dataset.index=(index+1).toString()}))}